{
  "output_schemas": {
    "fetch_data": {
      "properties": {
        "status_code": {
          "description": "HTTP response status",
          "type": "integer"
        },
        "body": {
          "description": "Response body as JSON",
          "type": "object"
        }
      },
      "required": [
        "status_code",
        "body"
      ],
      "title": "HttpRequestOutput",
      "type": "object"
    }
  },
  "input_schemas": {
    "custom_form_input": {
      "properties": {
        "filename": {
          "description": "Name of uploaded file",
          "type": "string"
        },
        "mime_type": {
          "description": "MIME type of uploaded file",
          "type": "string"
        },
        "document_url": {
          "description": "URL to uploaded document",
          "type": "string"
        },
        "metadata": {
          "description": "File metadata",
          "type": "object"
        }
      },
      "required": [
        "filename",
        "mime_type",
        "document_url"
      ],
      "title": "CustomFormInput",
      "type": "object"
    }
  },
  "dynamic_data": {
    "read_sheet": {
      "spreadsheet_id": {
        "options": [
          {
            "label": "Sales Data 2024",
            "value": "abc123"
          },
          {
            "label": "Customer List",
            "value": "def456"
          }
        ]
      }
    }
  },
  "validation_errors": [
    "Task 'invalid_task' uses unknown task executor 'nonexistent_executor'"
  ]
}
